import{_ as n,C as s,o as r,c as i,j as t,a as h,t as c,E as d,a1 as l}from"./chunks/framework.90UQlTmt.js";const p="/plugin-rest-cache/screenshots/settings-overview.png",g="/plugin-rest-cache/screenshots/edit-view-panel.png",_=JSON.parse('{"title":"Admin panel","description":"","frontmatter":{"title":"Admin panel"},"headers":[],"relativePath":"guide/admin/index.md","filePath":"guide/admin/index.md","lastUpdated":1786660168000}'),u={name:"guide/admin/index.md"},m={id:"frontmatter-title",tabindex:"-1"};function f(a,e,y,w,b,v){const o=s("Badge");return r(),i("div",null,[t("h1",m,[h(c(a.$frontmatter.title)+" ",1),e[0]||(e[0]=t("a",{class:"header-anchor",href:"#frontmatter-title","aria-label":'Permalink to "{{ $frontmatter.title }}"'},"​",-1))]),d(o,{type:"tip",text:"since 5.1.0"}),e[1]||(e[1]=l('<p>The plugin adds a dashboard under <strong>Settings → REST Cache</strong>, a widget on the admin homepage, and purge controls inside the content manager.</p><h2 id="dashboard" tabindex="-1">Dashboard <a class="header-anchor" href="#dashboard" aria-label="Permalink to &quot;Dashboard&quot;">​</a></h2><p><img src="'+p+'" alt="The REST Cache settings page, showing cached entry counts, the resolved strategy, and a table of cached content types"></p><p>Four figures across the top:</p><ul><li><strong>Cached entries</strong> — how many responses are currently stored.</li><li><strong>Stored ETags</strong> — companions to those entries, counted separately so they do not inflate the entry count.</li><li><strong>Cached content types</strong> — how many content types are configured.</li><li><strong>Provider</strong> — which provider is in use, and the default <code>maxAge</code>.</li></ul><p>Only the provider&#39;s <strong>name</strong> is shown, never its options. For Redis those options hold connection details, and holding the permission to read this page does not make someone an operator entitled to credentials.</p><p>Below that, the resolved strategy — the flags as the plugin actually resolved them, not as they were written, so this is the place to confirm that a setting took effect.</p><h3 id="cached-content-types" tabindex="-1">Cached content types <a class="header-anchor" href="#cached-content-types" aria-label="Permalink to &quot;Cached content types&quot;">​</a></h3><p>One row per configured content type, with the number of entries it currently holds, its <code>maxAge</code>, and the routes that were resolved for it. If a route you expected is missing here, it was not registered — that is the fastest way to spot a path that does not match what Strapi mounted.</p><p>A row may carry a badge:</p><ul><li><strong>Keyed per caller</strong> — <code>keys.useAuth</code> is on, so entries are stored separately per authenticated caller.</li><li><strong>Shared across callers</strong> — <code>hitpass</code> is off but <code>keys.useAuth</code> is not set, so one caller&#39;s response can be served to another. The server also warns about this at boot; the badge is here because nobody reads boot logs.</li></ul><p>The <strong>Purge</strong> button clears every entry for that content type, and for the content types related to it when <code>clearRelatedCache</code> is on. The counts update without a page reload.</p><div class="info custom-block"><p class="custom-block-title">Permissions</p><p>The dashboard requires <code>plugin::rest-cache.cache.read-strategy</code>, and purging requires <code>plugin::rest-cache.cache.purge</code>. Grant them under <strong>Settings → Roles</strong>.</p><p>Hiding a control is presentation, not protection: every admin route carries a permission policy for the same action, so the server refuses regardless of what the panel renders.</p></div><h2 id="homepage-widget" tabindex="-1">Homepage widget <a class="header-anchor" href="#homepage-widget" aria-label="Permalink to &quot;Homepage widget&quot;">​</a></h2><p>A compact view of the same figures, with a link through to the dashboard. It shares its data with the dashboard, so opening one after the other does not refetch, and a purge from either updates both.</p><h2 id="content-manager" tabindex="-1">Content manager <a class="header-anchor" href="#content-manager" aria-label="Permalink to &quot;Content manager&quot;">​</a></h2><p><img src="'+g+'" alt="The content manager edit view, with a REST Cache panel stating how long responses for the entry are cached"></p><p>Opening an entry of a cached content type shows a <strong>REST Cache</strong> panel saying how long its responses are cached for. That is the number someone needs when they have just published a change and are looking at stale output: it answers whether to wait or to purge.</p><p>The entry&#39;s <strong>More actions</strong> menu gains <strong>Purge REST Cache</strong>, which clears the cached responses for that entry. The list view has an equivalent control that purges the whole content type.</p><p>These appear only for content types that are actually in the configured strategy, so their presence is itself a signal that caching applies.</p><div class="tip custom-block"><p class="custom-block-title">You rarely need these</p><p>Invalidation is automatic. Every write through the document service — REST, GraphQL, the content manager, Content Releases, or a custom <code>strapi.documents()</code> call — purges what it affects. The manual controls are for the cases automation cannot see, such as content changed directly in the database.</p><p>See <a href="./../invalidation/">Invalidation</a>.</p></div>',21))])}const S=n(u,[["render",f]]);export{_ as __pageData,S as default};
